  describe('collects HostFormFactor as an artifact', () => {
    const requestedUrl = 'https://example.com';

    /**
     * @param {string} name
     * @param {string} userAgent
     * @param {string} expectedValue
     */
    function test(name, userAgent, expectedValue) {
