    const records = NetworkRecorder.recordsFromLogs(devtoolsLogs);
    expect(records).toMatchObject([
      {url: 'http://example.com', sessionId: undefined},
      {url: 'http://iframe.com', sessionId: '1'},
      {url: 'http://other-iframe.com', sessionId: '2'},
